// echoing-grotto — конвейер: пещеры in D фригийский (0 1 3 5 7 8 10), 111 BPM. Generated by MathMusic
// (style factorycave, seed 1): descent → ore veins → the deep → tunnels → drills → crystal cavern → silence.
// Themes: A — Deep Ore (пещеры) (recomposed), B — пещера из chiptune (as written); the bridge melody is newly
// composed on the rhythm of a theme from classical. Computed parts: an improvised solo, a counter-melody from the chords, the theme at half speed in the outro.
// It is an ordinary song file: change anything; the melodies can be drawn in the piano roll (P).
// x is time in beats; n counts semitones from C4 (MIDI 60).
import { TAU, delay, exp, filter, floor, hz, mod, noise, reverb, sin, smooth, supersaw } from '../src/engine.js'
import {
  VOWELS, arrangement, chorus, clankTone, clapDrum, clubKick, crashCymbal, duck, hash, hatDrum, improvise, kickDrum, monoSynth, notesAt, pan, pluckTone, poly, rimDrum, shakerDrum, snareDrum, trigger, vibesTone, voice,
} from '../src/instruments.js'

const SECTIONS = [[0,"descent"],[16,"ore veins"],[80,"the deep"],[112,"tunnels"],[144,"drills"],[176,"crystal cavern"],[240,"silence"]]
const END = 256
const part = arrangement(SECTIONS)
const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",1],[16,"theme",2],[80,"bridge",1],[112,"themeB",2],[144,"solo",3],[176,"final",3],[240,"outro",0]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

